ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns ns1 urn:sqad:orders
var rawOrders = attributes.queryParams.orders default null
var queries = rawOrders match {
    case arr if (arr is Array) -> arr
    case null -> []
    else -> [rawOrders]
}
---
soapenv#Envelope: {
    soapenv#Header: null,
    soapenv#Body: {
        ns1#dsOrderIntListQuery: (queries default []) map (orderNumber) -> {
            ns1#ttOrderIntList: {
                ns1#BusinessLine: "Progress",
                ns1#TargetApp: "ORA",
                ns1#Domain: "USA",
                ns1#Entity: "100",
                ns1#SalesOrder: orderNumber
            }
        }
    }
}

%dw 2.0
output application/json
import stripNamespaces from dw::core::XML
fun toArray(value) =
    value match {
        case arr if (arr is Array) -> arr
        case null -> []
        else -> [value]
    }
var xml = stripNamespaces(payload)
var body = xml.Envelope.Body
var rows = toArray(body.dsOrderIntListQueryResponse.ttOrderIntList)
---
{
    orderRecords: rows map (item) -> {
        businessLine: item.BusinessLine default null,
        targetApp: item.TargetApp default null,
        domain: item.Domain default null,
        entity: item.Entity default null,
        salesOrder: item.SalesOrder default null,
        orderStatus: item.OrderStatus default null,
        billingFrequency: item.BillingFrequency default null,
        orderOid: item.OrderOID default null
    }
}

