%dw 2.0
output application/json
import stripNamespaces from dw::core::XML
fun toArray(value) =
    value match {
        case arr if (arr is Array) -> arr
        case null -> []
        else -> [value]
    }
var xml = stripNamespaces(payload)
var body = xml.Envelope.Body
var customers = toArray(body.CustomerQueryResponse.CustomerList.Customer)
---
{
    customers: customers map (item) -> {
        cmAddr: item.CmAddr default null,
        cmDomain: item.CmDomain default null,
        cmActive: (item.CmActive default null) as Boolean?,
        cmChannel: item.CmChannel default null,
        cmClass: item.CmClass default null,
        addresses: toArray(item.Addresses.Address) map (address) -> {
            adAddr: address.AdAddr default null,
            adCity: address.AdCity default null,
            adCountry: address.AdCountry default null,
            addressLines: toArray(address.AddressLines.AddressLine) map (line) -> {
                addressId: line.AddressId default null,
                addressName: line.AddressName default null,
                contacts: toArray(line.Contacts.Contact) map (contact) -> {
                    contactId: contact.ContactId default null,
                    contactName: contact.ContactName default null,
                    contactEmail: contact.ContactEmail default null
                }
            }
        },
        codeMasters: toArray(item.CodeMasters.CodeMaster) map (code) -> {
            codeDomain: code.CodeDomain default null,
            codeFldname: code.CodeFldname default null,
            codeValue: code.CodeValue default null
        },
        debtors: toArray(item.Debtors.Debtor) map (debtor) -> {
            debtorId: debtor.DebtorId default null,
            debtorCode: debtor.DebtorCode default null,
            debtorFixedCredLimtC: debtor.DebtorFixedCredLimtC default null
        },
        internalRepresentatives: toArray(item.InternalRepresentatives.InternalRepresentative) map (rep) -> {
            irlAddr: rep.IrlAddr default null,
            irlEmp: rep.IrlEmp default null,
            irlType: rep.IrlType default null
        }
    }
}
